const wc = $('When Called').first().json || {};
const taskId = wc.clickup_task_id || '';
let input = {}; try { input = JSON.parse(wc.tool_input_json || '{}') || {}; } catch (e) {}
const limit = Number(input.limit) > 0 ? Number(input.limit) : 0;
const since = input.since ? Number(input.since) : 0;
let sr = {}; try { sr = $('Call Assemble Task Context').first().json || {}; } catch (e) {}
let comments = Array.isArray(sr.task_comments) ? sr.task_comments : null;
let ws = '', wm = '', wd = '';
if (comments === null) {
  ws = 'managed-agents/tail-comments-failed';
  wm = 'Pobranie komentarzy zadania ' + taskId + ' nie powiodlo sie (narzedzie get_task_comments).';
  wd = 'task=' + taskId;
  comments = [];
}
if (since) comments = comments.filter(function(c){ return Number((c && c.date) || 0) >= since; });
let used = comments;
if (limit && comments.length > limit) used = comments.slice(0, limit);
const lines = [];
lines.push('Komentarze zadania ' + taskId + ' (' + used.length + (limit && comments.length > limit ? ' z ' + comments.length : '') + '):');
if (used.length === 0) lines.push('(brak komentarzy)');
for (const c of used) { lines.push(((c && c.author) || 'nieznany') + ': ' + ((c && c.text) || '')); }
const content = [{ type: 'text', text: lines.join('\n') }];
return [{ json: {
  status: ws ? 'partial' : (used.length ? 'ok' : 'empty'),
  tool_result_content_json: JSON.stringify(content),
  new_images_json: '[]',
  new_warnings_json: '[]',
  _warn_source: ws, _warn_msg: wm, _warn_details: wd
} }];

const wc = $('When Called').first().json || {};
const taskId = wc.clickup_task_id || '';
let input = {}; try { input = JSON.parse(wc.tool_input_json || '{}') || {}; } catch (e) {}
const depth = Number(input.depth) > 0 ? Number(input.depth) : 0;
let ctx = {}; try { ctx = $('Call Assemble Parent Context').first().json || {}; } catch (e) {}
let chain = Array.isArray(ctx.ancestor_chain) ? ctx.ancestor_chain : null;
let ws = '', wm = '', wd = '';
if (chain === null || !ctx.current_task) {
  ws = 'managed-agents/tail-parents-failed';
  wm = 'Pobranie kontekstu nadrzednego zadania ' + taskId + ' nie powiodlo sie (narzedzie get_parent_chain).';
  wd = 'task=' + taskId;
  chain = chain || [];
}
let used = chain.slice().reverse();
if (depth && used.length > depth) used = used.slice(used.length - depth);
const lines = [];
if (used.length === 0) {
  lines.push('Zadanie ' + taskId + ' nie ma zadan nadrzednych (brak lancucha rodzicow).');
} else {
  lines.push('Lancuch zadan nadrzednych zadania ' + taskId + ' (od najogolniejszego do najblizszego), ' + used.length + ' poziom(ow):');
  for (const a of used) { lines.push(''); lines.push('## ' + ((a && a.name) || '(bez nazwy)')); if (a && a.description) lines.push(a.description); }
}
const content = [{ type: 'text', text: lines.join('\n') }];
return [{ json: {
  status: ws ? 'partial' : 'ok',
  tool_result_content_json: JSON.stringify(content),
  new_images_json: '[]',
  new_warnings_json: '[]',
  _warn_source: ws, _warn_msg: wm, _warn_details: wd
} }];

const wc = $('When Called').first().json || {};
const taskId = wc.clickup_task_id || '';
let task = {}; try { task = $('Get Attachment List').first().json || {}; } catch (e) {}
let atts = Array.isArray(task.attachments) ? task.attachments : null;
let ws = '', wm = '', wd = '';
if (atts === null) {
  ws = 'managed-agents/tail-attachments-failed';
  wm = 'Pobranie listy zalacznikow zadania ' + taskId + ' nie powiodlo sie (narzedzie list_attachments).';
  wd = 'task=' + taskId;
  atts = [];
}
const items = atts.map(function(a){ return { attachment_id: String((a && a.id) || ''), title: (a && a.title) || '', ext: String((a && a.extension) || '').toLowerCase(), mime: String((a && a.mimetype) || '').toLowerCase(), size_bytes: Number((a && a.size) || 0) }; });
const lines = [];
lines.push('Zalaczniki zadania ' + taskId + ' (' + items.length + '):');
if (items.length === 0) lines.push('(brak zalacznikow)');
for (const it of items) { lines.push('- attachment_id="' + it.attachment_id + '" | ' + (it.title || '(bez nazwy)') + ' | ' + (it.mime || it.ext || '?') + ' | ' + (it.size_bytes ? Math.round(it.size_bytes / 1024) + ' KB' : '? KB')); }
lines.push('');
lines.push('Aby pobrac TRESC konkretnego zalacznika (dokument -> tekst, obraz -> wizja), wywolaj get_attachment z { attachment_id } wybranym z powyzszej listy.');
const content = [{ type: 'text', text: lines.join('\n') }];
return [{ json: {
  status: ws ? 'partial' : (items.length ? 'ok' : 'empty'),
  tool_result_content_json: JSON.stringify(content),
  new_images_json: '[]',
  new_warnings_json: '[]',
  _warn_source: ws, _warn_msg: wm, _warn_details: wd
} }];

const wc = $('When Called').first().json || {};
const taskId = wc.clickup_task_id || '';
let input = {}; try { input = JSON.parse(wc.tool_input_json || '{}') || {}; } catch (e) {}
const onlyAttId = String(input.attachment_id || input.att_id || '').trim();
return [{ json: { clickup_task_id: taskId, only_att_id: onlyAttId, _missing_id: !onlyAttId } }];

const wc = $('When Called').first().json || {};
const taskId = wc.clickup_task_id || '';
let argsId = ''; try { argsId = $('Build Read Input Args').first().json.only_att_id || ''; } catch (e) {}
const ri = (($('Call Read Input (single)').first() || {}).json) || {};
const blocks = Array.isArray(ri.blocks) ? ri.blocks : [];
const up = (($('Upload Tail Images').first() || {}).json) || {};
const fileMap = Array.isArray(up.file_map) ? up.file_map : [];
const fileById = {};
for (const f of fileMap) { if (f && f.file_id) { if (f.order != null) fileById['o:' + f.order] = f.file_id; if (f.source_ref != null) fileById['s:' + f.source_ref] = f.file_id; if (f.url) fileById['r:' + f.url] = f.file_id; } }
const sorted = blocks.slice().sort(function(a, b){ return ((a && a.order) || 0) - ((b && b.order) || 0); });
const body = [];
let docCount = 0, imgCount = 0, imgFailed = 0, brak = 0;
for (const b of sorted) {
  if (!b) continue;
  if (b.type === 'text') { const md = b.md || ''; if (md) { body.push({ type: 'text', text: md }); if (md.indexOf('[BRAK') === 0) brak++; else docCount++; } }
  else if (b.type === 'image') { const fid = fileById['o:' + b.order] || (b.source_ref != null ? fileById['s:' + b.source_ref] : null) || (b.ref ? fileById['r:' + b.ref] : null); if (fid) { body.push({ type: 'image', source: { type: 'file', file_id: fid } }); imgCount++; } else { imgFailed++; body.push({ type: 'text', text: '[obraz niedostepny: ' + (b.alt || b.source_ref || '') + ']' }); } }
}
const found = body.length > 0;
let ws = '', wm = '', wd = '';
if (!found) {
  ws = 'managed-agents/tail-attachment-empty';
  wm = 'Zalacznik ' + argsId + ' zadania ' + taskId + ' nie zwrocil tresci (get_attachment) - byc moze nie istnieje lub ekstrakcja zawiodla.';
  wd = 'task=' + taskId + '; attachment=' + argsId;
} else if (imgFailed > 0 || brak > 0) {
  ws = 'managed-agents/tail-attachment-partial';
  wm = 'Ekstrakcja zalacznika ' + argsId + ' zadania ' + taskId + ' czesciowa (get_attachment).';
  wd = 'task=' + taskId + '; attachment=' + argsId + '; brak=' + brak + '; obrazy_niepobrane=' + imgFailed;
}
const header = found
  ? ('Tresc zalacznika ' + argsId + ' zadania ' + taskId + ': ' + docCount + ' dok., ' + imgCount + ' obr.' + (imgFailed ? (' (' + imgFailed + ' obr. nie pobrano)') : ''))
  : ('Nie znaleziono tresci zalacznika ' + argsId + ' w zadaniu ' + taskId + '. Sprawdz attachment_id przez list_attachments.');
const content = [{ type: 'text', text: header }].concat(body);
return [{ json: {
  status: found ? ((imgFailed || brak) ? 'partial' : 'ok') : 'empty',
  tool_result_content_json: JSON.stringify(content),
  new_images_json: '[]',
  new_warnings_json: '[]',
  _warn_source: ws, _warn_msg: wm, _warn_details: wd
} }];

const content = [{ type: 'text', text: 'Narzedzie get_attachment wymaga parametru attachment_id. Najpierw wywolaj list_attachments, aby poznac attachment_id zalacznikow tego zadania, a nastepnie wywolaj get_attachment z wybranym attachment_id.' }];
return [{ json: {
  status: 'error',
  tool_result_content_json: JSON.stringify(content),
  new_images_json: '[]',
  new_warnings_json: '[]',
  _warn_source: '', _warn_msg: '', _warn_details: ''
} }];

const wc = $('When Called').first().json || {};
const name = wc.tool_name || 'unknown';
const content = [{ type: 'text', text: 'Narzedzie "' + name + '" nie jest obslugiwane przez ten handler. Pracuj na podstawie dostepnego kontekstu.' }];
return [{ json: {
  status: 'error',
  tool_result_content_json: JSON.stringify(content),
  new_images_json: '[]',
  new_warnings_json: '[]',
  _warn_source: 'managed-agents/tail-unknown-tool', _warn_msg: 'Tail handler otrzymal nieznane narzedzie: ' + name, _warn_details: 'tool=' + name
} }];

const r = ($('Merge Result').first() || {}).json || {};
return [{ json: {
  status: r.status || 'ok',
  tool_result_content_json: r.tool_result_content_json || JSON.stringify([{ type: 'text', text: 'Brak wyniku narzedzia.' }]),
  new_images_json: r.new_images_json || '[]',
  new_warnings_json: r.new_warnings_json || '[]'
} }];
